    to handle the special characters '.', '*', and '+'.
    """

    def dp(p_index: int, t_index: int) -> bool:
        if p_index == len(pattern):
            return t_index == len(text)

        first_match = t_index < len(text) and (pattern[p_index] == text[t_index] or pattern[p_index] == '.')

        if (p_index + 1) < len(pattern) and pattern[p_index + 1] == '*':
            return (dp(p_index + 2, t_index) or 
                    (first_match and dp(p_index, t_index + 1)))

        elif (p_index + 1) < len(pattern) and pattern[p_index + 1] == '+':
            return first_match and (dp(p_index, t_index + 1) or dp(p_index + 2, t_index))

