    """

    def backtrack(p_index: int, t_index: int) -> bool:
        if p_index == len(pattern):
            return t_index == len(text)

        is_current_match = (t_index < len(text) and 
                            (pattern[p_index] == text[t_index] or pattern[p_index] == '.'))

        if p_index + 1 < len(pattern):            
            if pattern[p_index + 1] == '*':
                # Two scenarios: we either ignore the '*' or we use it
                return (backtrack(p_index + 2, t_index) or 
                        (is_current_match and backtrack(p_index, t_index + 1)))
            elif pattern[p_index + 1] == '+':
                if is_current_match:
                    return backtrack(p_index, t_index + 1)   # Use at least one match
                else:
                    return False

        return is_current_match and backtrack(p_index + 1, t_index + 1)

    return backtrack(0, 0)
